  if (p_palette < 0.5) c = vec3(v * 1.5, v * v * 1.2, v * v * v * 0.8);
  else if (p_palette < 1.5) c = vec3(v * v * 0.6, v * 1.1, v * 1.6);
  else c = hsv2rgb(vec3(0.7 - v * 0.7, 0.9, v * 1.3));
  return vec4(c, 1.0);
