  // Beat-Modus: neue Farbe bei jedem Schlag
  if (p_sync > 0.5) { k = uBeatCount; on = step(pow(0.86, 1.0 + p_duty * 25.0), uBeat); }
  vec3 c = hsv2rgb(vec3(hash11(k * 1.73 + uSeed * 91.0), p_sat, 1.0));
